package com.alibaba.nacos.console.controller.v3.naming;

import com.alibaba.nacos.api.exception.api.NacosApiException;
import com.alibaba.nacos.api.model.v2.Result;
import com.alibaba.nacos.api.naming.pojo.Instance;
import com.alibaba.nacos.console.proxy.naming.InstanceProxy;
import com.alibaba.nacos.naming.model.form.InstanceForm;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;

@ExtendWith(MockitoExtension.class)
class ConsoleInstanceControllerTest {

    @Mock
    private InstanceProxy instanceProxy;

    @InjectMocks
    private ConsoleInstanceController controller;

    @Test
    void removeInstance_shouldRejectEphemeralInstanceDeletion() {
        InstanceForm form = buildInstanceForm(true);

        NacosApiException exception = assertThrows(NacosApiException.class, () -> controller.removeInstance(form));

        assertEquals("Console only supports deregistering persistent instances", exception.getMessage());
        verifyNoInteractions(instanceProxy);
    }

    @Test
    void removeInstance_shouldDelegatePersistentInstanceDeletion() throws Exception {
        InstanceForm form = buildInstanceForm(false);
        doNothing().when(instanceProxy).removeInstance(any(InstanceForm.class), any(Instance.class));

        Result<String> result = controller.removeInstance(form);

        assertNotNull(result);
        assertEquals("ok", result.getData());

        ArgumentCaptor<InstanceForm> formCaptor = ArgumentCaptor.forClass(InstanceForm.class);
        ArgumentCaptor<Instance> instanceCaptor = ArgumentCaptor.forClass(Instance.class);
        verify(instanceProxy).removeInstance(formCaptor.capture(), instanceCaptor.capture());

        assertSame(form, formCaptor.getValue());

        Instance instance = instanceCaptor.getValue();
        assertEquals("127.0.0.1", instance.getIp());
        assertEquals(8848, instance.getPort());
        assertEquals("cluster-a", instance.getClusterName());
        assertFalse(instance.isEphemeral());
    }

    private InstanceForm buildInstanceForm(boolean ephemeral) {
        InstanceForm form = new InstanceForm();
        form.setNamespaceId("public");
        form.setServiceName("demo-service");
        form.setGroupName("DEFAULT_GROUP");
        form.setClusterName("cluster-a");
        form.setIp("127.0.0.1");
        form.setPort(8848);
        form.setEphemeral(ephemeral);
        form.setEnabled(true);
        form.setWeight(1.0D);
        form.setMetadata("{}");
        return form;
    }
}

