package com.alibaba.nacos.console.proxy.ai;

import com.alibaba.nacos.console.handler.ai.SkillHandler;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.isNull;
import static org.mockito.ArgumentMatchers.same;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.withSettings;

/**
 * Tests for the skill upload delegation chain with the new targetVersion parameter.
 */
class SkillProxyTest {

    @Test
    void skillHandlerDefaultUploadSkillFromZipMethodsDelegateToTargetVersionAwareMethod() throws Exception {
        SkillHandler skillHandler = mock(SkillHandler.class, withSettings().defaultAnswer(CALLS_REAL_METHODS));
        byte[] zipBytes = new byte[] {1, 2, 3};

        doReturn("resolved-from-two-arg")
                .when(skillHandler)
                .uploadSkillFromZip(eq("namespace-1"), same(zipBytes), eq(false), isNull(String.class));
        doReturn("resolved-from-three-arg")
                .when(skillHandler)
                .uploadSkillFromZip(eq("namespace-1"), same(zipBytes), eq(true), isNull(String.class));

        assertEquals("resolved-from-two-arg", skillHandler.uploadSkillFromZip("namespace-1", zipBytes));
        assertEquals("resolved-from-three-arg", skillHandler.uploadSkillFromZip("namespace-1", zipBytes, true));

        verify(skillHandler).uploadSkillFromZip("namespace-1", zipBytes, false, null);
        verify(skillHandler).uploadSkillFromZip("namespace-1", zipBytes, true, null);
    }

    @Test
    void uploadSkillFromZipDelegatesTargetVersionAndBackwardCompatibleOverload() throws Exception {
        SkillHandler skillHandler = mock(SkillHandler.class);
        SkillProxy skillProxy = createSkillProxy(skillHandler);
        byte[] zipBytes = new byte[] {9, 8, 7};

        doReturn("skill-with-target-version")
                .when(skillHandler)
                .uploadSkillFromZip(eq("namespace-2"), same(zipBytes), eq(false), eq("2.1.0"));
        doReturn("skill-with-null-target-version")
                .when(skillHandler)
                .uploadSkillFromZip(eq("namespace-2"), same(zipBytes), eq(true), isNull(String.class));

        assertEquals("skill-with-target-version",
                skillProxy.uploadSkillFromZip("namespace-2", zipBytes, false, "2.1.0"));
        assertEquals("skill-with-null-target-version",
                skillProxy.uploadSkillFromZip("namespace-2", zipBytes, true));

        verify(skillHandler).uploadSkillFromZip("namespace-2", zipBytes, false, "2.1.0");
        verify(skillHandler).uploadSkillFromZip("namespace-2", zipBytes, true, null);
    }

    private static SkillProxy createSkillProxy(SkillHandler skillHandler) throws Exception {
        for (Constructor<?> constructor : SkillProxy.class.getDeclaredConstructors()) {
            constructor.setAccessible(true);
            Class<?>[] parameterTypes = constructor.getParameterTypes();
            if (parameterTypes.length == 1 && SkillHandler.class.isAssignableFrom(parameterTypes[0])) {
                return (SkillProxy) constructor.newInstance(skillHandler);
            }
            if (parameterTypes.length == 0) {
                SkillProxy proxy = (SkillProxy) constructor.newInstance();
                Field field = SkillProxy.class.getDeclaredField("skillHandler");
                field.setAccessible(true);
                field.set(proxy, skillHandler);
                return proxy;
            }
        }
        throw new IllegalStateException("No suitable constructor found for SkillProxy");
    }
}

