import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.lang.reflect.Method;

import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.isNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

/**
 * Tests for the legacy latest mirror cleanup added to PromptOperationServiceImpl.
 */
public class PromptOperationServiceImplTest {

    private PromptOperationServiceImpl createService(ConfigOperationService configOperationService) {
        AiResourcePersistService aiResourcePersistService = mock(AiResourcePersistService.class);
        AiResourceVersionPersistService aiResourceVersionPersistService = mock(AiResourceVersionPersistService.class);
        PublishPipelineExecutor publishPipelineExecutor = mock(PublishPipelineExecutor.class);
        PipelineExecutionRepository pipelineExecutionRepository = mock(PipelineExecutionRepository.class);

        return new PromptOperationServiceImpl(aiResourcePersistService, aiResourceVersionPersistService,
                publishPipelineExecutor, pipelineExecutionRepository, configOperationService);
    }

    private void invokeDeleteLegacyLatestMirror(PromptOperationServiceImpl service, String namespaceId,
            String promptKey) throws Exception {
        Method method = PromptOperationServiceImpl.class.getDeclaredMethod("deleteLegacyLatestMirror",
                String.class, String.class);
        method.setAccessible(true);
        method.invoke(service, namespaceId, promptKey);
    }

    @Test
    public void testDeleteLegacyLatestMirrorDeletesExpectedConfig() throws Exception {
        ConfigOperationService configOperationService = mock(ConfigOperationService.class);
        PromptOperationServiceImpl service = createService(configOperationService);

        String namespaceId = "dev";
        String promptKey = "marketing-prompt";
        String expectedDataId = PromptVersionUtils.buildDataId(promptKey);

        invokeDeleteLegacyLatestMirror(service, namespaceId, promptKey);

        verify(configOperationService).deleteConfig(eq(expectedDataId), eq(Constants.Prompt.PROMPT_GROUP),
                eq(namespaceId), isNull(), isNull(), eq("nacos"), isNull());
    }

    @Test
    public void testDeleteLegacyLatestMirrorSwallowsDeletionFailure() throws Exception {
        ConfigOperationService configOperationService = mock(ConfigOperationService.class);
        PromptOperationServiceImpl service = createService(configOperationService);

        Mockito.doThrow(new RuntimeException("config service unavailable"))
                .when(configOperationService)
                .deleteConfig(Mockito.anyString(), Mockito.anyString(), Mockito.anyString(),
                        Mockito.any(), Mockito.any(), Mockito.anyString(), Mockito.any());

        String namespaceId = "dev";
        String promptKey = "marketing-prompt";

        // Should not throw, because the helper must swallow exceptions and only log a warning.
