package com.alibaba.nacos.console.controller.v3.naming;

import com.alibaba.nacos.api.exception.NacosException;
import com.alibaba.nacos.api.exception.api.NacosApiException;
import com.alibaba.nacos.api.model.v2.Result;
import com.alibaba.nacos.api.naming.pojo.Instance;
import com.alibaba.nacos.console.handler.impl.noop.naming.InstanceNoopHandler;
import com.alibaba.nacos.console.proxy.naming.InstanceProxy;
import com.alibaba.nacos.naming.model.form.InstanceForm;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

/**
 * Tests for DELETE /v3/console/ns/instance flow and related noop handler behavior.
 */
class ConsoleInstanceControllerRemoveInstanceTest {

    @Test
    void removeInstanceShouldRejectEphemeralInstancesWithBadRequest() throws Exception {
        // Prepare controller with a mocked proxy (won't be reached due to validation failure)
        InstanceProxy mockProxy = mock(InstanceProxy.class);
        ConsoleInstanceController controller = new ConsoleInstanceController(mockProxy);

        // Build an InstanceForm with ephemeral=true (should be rejected)
        InstanceForm form = new InstanceForm();
        form.setNamespaceId("public");
        form.setGroupName("DEFAULT_GROUP");
        form.setServiceName("test-service");
        form.setClusterName("DEFAULT");
        form.setIp("127.0.0.1");
        form.setPort(8080);
        form.setEphemeral(true);

        NacosApiException ex = assertThrows(NacosApiException.class, () -> controller.removeInstance(form));
        // HttpStatus.BAD_REQUEST.value() = 400 is placed into errCode for NacosApiException
        assertEquals(400, ex.getErrCode());
        assertEquals("Console only supports deregistering persistent instances", ex.getErrMsg());

        // Ensure proxy is never called when validation fails
        verify(mockProxy, never()).removeInstance(any(), any());
    }

    @Test
    void removeInstanceShouldDelegateToProxyForPersistentInstances() throws Exception {
        InstanceProxy mockProxy = mock(InstanceProxy.class);
        ConsoleInstanceController controller = new ConsoleInstanceController(mockProxy);

        InstanceForm form = new InstanceForm();
        form.setNamespaceId("public");
        form.setGroupName("DEFAULT_GROUP");
        form.setServiceName("test-service");
        form.setClusterName("DEFAULT");
        form.setIp("10.0.0.1");
        form.setPort(8848);
        form.setEphemeral(false);

        Result<String> result = controller.removeInstance(form);
        assertNotNull(result);
        assertEquals("ok", result.getData());

        ArgumentCaptor<Instance> instanceCaptor = ArgumentCaptor.forClass(Instance.class);
        verify(mockProxy, times(1)).removeInstance(eq(form), instanceCaptor.capture());

        Instance captured = instanceCaptor.getValue();
        assertNotNull(captured);
        assertEquals("10.0.0.1", captured.getIp());
        assertEquals(8848, captured.getPort());
        assertEquals("DEFAULT", captured.getClusterName());
        // The service name is composite inside Instance (groupName@@serviceName), but core assertions above are sufficient.
    }

    @Test
    void noopHandlerRemoveInstanceShouldThrowServerNotImplementedWhenNamingModuleIsDisabled() {
        InstanceNoopHandler handler = new InstanceNoopHandler();

        NacosApiException exception = assertThrows(NacosApiException.class,
                () -> handler.removeInstance(null, null));

        assertEquals(NacosException.SERVER_NOT_IMPLEMENTED, exception.getErrCode());
        // Be tolerant to exact message text while ensuring it conveys disabled/not-enabled semantics
        String msg = exception.getErrMsg() == null ? "" : exception.getErrMsg().toLowerCase();
        assertTrue(msg.contains("disabled") || msg.contains("not enabled"));
        assertTrue(exception.getMessage() != null && !exception.getMessage().isEmpty());
    }
}

