    @Test
    void runPipelineExecutionShouldUseProvidedCompletionCallback() throws NacosException {
        AiResourceManager manager = new TestableAiResourceManager(
                aiResourcePersistService, aiResourceVersionPersistService, pipelineExecutionRepository);

        ResourceFilesPipelineContext ctx = mock(ResourceFilesPipelineContext.class);
        PublishPipelineExecutor executor = mock(PublishPipelineExecutor.class);
        PipelineCallback callback = mock(PipelineCallback.class);

        AtomicReference<PipelineCallback> capturedCallback = new AtomicReference<>();
        when(executor.execute(any(ResourceFilesPipelineContext.class), any(PipelineCallback.class), anyString()))
                .thenAnswer(invocation -> {
                    capturedCallback.set(invocation.getArgument(1));
                    return "";
                });

        boolean result = manager.runPipelineExecution(
                NAMESPACE_ID, NAME, TYPE, VERSION, ctx, executor, callback);

        assertFalse(result);
        assertSame(callback, capturedCallback.get());
        verify(executor).execute(any(ResourceFilesPipelineContext.class), any(PipelineCallback.class), anyString());
    }

