    @Test
    void onSkillPipelineCompleteShouldInvokeBaseHandlerOnlyWhenDisabled() throws Exception {
        SkillOperationServiceImpl service = new SkillOperationServiceImpl(
                aiResourcePersistService,
                aiResourceVersionPersistService,
                mock(PublishPipelineExecutor.class),
                mock(SkillIndexManifestService.class),
                mock(AiResourceManager.class));
        AiResourceManager resourceManager = mock(AiResourceManager.class);

        setField(service, "resourceManager", resourceManager);

        PipelineExecutionResult result = mock(PipelineExecutionResult.class);
        when(result.getStatus()).thenReturn(PipelineExecutionStatus.APPROVED);

        try (MockedStatic<EnvUtil> env = mockStatic(EnvUtil.class)) {
            env.when(() -> EnvUtil.getProperty(anyString(), Mockito.eq(Boolean.class), anyBoolean())).thenReturn(false);

            // invoke private method onSkillPipelineComplete
            invokeOnSkillPipelineComplete(service, NAMESPACE_ID, NAME, VERSION, result);

            verify(resourceManager).onPipelineComplete(NAMESPACE_ID, NAME, "skill", VERSION, result);
            Mockito.verify(resourceManager, Mockito.never()).doSystemPublish(anyString(), anyString(), anyString(),
                    anyString(), Mockito.anyBoolean());
        }
    }

    @Test
    void onSkillPipelineCompleteShouldAutoPublishWhenApprovedAndEnabled() throws Exception {
        SkillOperationServiceImpl service = new SkillOperationServiceImpl(
                aiResourcePersistService,
                aiResourceVersionPersistService,
                mock(PublishPipelineExecutor.class),
                mock(SkillIndexManifestService.class),
                mock(AiResourceManager.class));
        AiResourceManager resourceManager = mock(AiResourceManager.class);
        SkillIndexManifestService manifestService = mock(SkillIndexManifestService.class);
        AiResourceVersion versionRow = createVersion(AiResourceConstants.VERSION_STATUS_REVIEWING, null);

        setField(service, "resourceManager", resourceManager);
        setField(service, "manifestService", manifestService);

        when(resourceManager.doSystemPublish(NAMESPACE_ID, NAME, "skill", VERSION, true)).thenReturn(versionRow);

        SkillIndexManifest manifest = new SkillIndexManifest();
        manifest.setLabels(new java.util.HashMap<>());
        manifest.setVersions(new java.util.HashMap<>());
        when(manifestService.loadForUpdate(NAMESPACE_ID, NAME)).thenReturn(manifest);
        doNothing().when(manifestService).write(anyString(), anyString(), any(SkillIndexManifest.class));

        PipelineExecutionResult result = mock(PipelineExecutionResult.class);
        when(result.getStatus()).thenReturn(PipelineExecutionStatus.APPROVED);

        try (MockedStatic<EnvUtil> env = mockStatic(EnvUtil.class)) {
            env.when(() -> EnvUtil.getProperty(anyString(), Mockito.eq(Boolean.class), anyBoolean())).thenReturn(true);

            invokeOnSkillPipelineComplete(service, NAMESPACE_ID, NAME, VERSION, result);

            verify(resourceManager).onPipelineComplete(NAMESPACE_ID, NAME, "skill", VERSION, result);
            verify(resourceManager).doSystemPublish(NAMESPACE_ID, NAME, "skill", VERSION, true);

            ArgumentCaptor<SkillIndexManifest> cap = ArgumentCaptor.forClass(SkillIndexManifest.class);
            verify(manifestService).write(anyString(), anyString(), cap.capture());
            SkillIndexManifest written = cap.getValue();
            assertTrue(VERSION.equals(written.getLabels().get(AiResourceConstants.LABEL_LATEST)));
            assertTrue(written.getVersions().containsKey(VERSION));
        }
    }

    private static void invokeOnSkillPipelineComplete(SkillOperationServiceImpl service, String namespaceId,
            String name, String version, PipelineExecutionResult result) throws Exception {
        java.lang.reflect.Method m = SkillOperationServiceImpl.class.getDeclaredMethod(
                "onSkillPipelineComplete", String.class, String.class, String.class, PipelineExecutionResult.class);
        m.setAccessible(true);
        m.invoke(service, namespaceId, name, version, result);
    }

    private static void setField(Object target, String fieldName, Object value) throws Exception {
        Field f = target.getClass().getDeclaredField(fieldName);
        f.setAccessible(true);
        f.set(target, value);
    }

    private AiResource createMeta(String versionInfoJson) {
        AiResource meta = mock(AiResource.class);
        when(meta.getNamespaceId()).thenReturn(NAMESPACE_ID);
        when(meta.getName()).thenReturn(NAME);
        when(meta.getType()).thenReturn(TYPE);
        when(meta.getVersionInfo()).thenReturn(versionInfoJson);
        return meta;
    }

    private AiResourceVersion createVersion(String status, String publishPipelineInfoJson) {
        AiResourceVersion version = mock(AiResourceVersion.class);
        when(version.getNamespaceId()).thenReturn(NAMESPACE_ID);
        when(version.getName()).thenReturn(NAME);
        when(version.getType()).thenReturn(TYPE);
        when(version.getVersion()).thenReturn(VERSION);
        when(version.getStatus()).thenReturn(status);
        when(version.getPublishPipelineInfo()).thenReturn(publishPipelineInfoJson);
        when(version.getStorage()).thenReturn("{}");
        return version;
    }
